'use client'

import {
    Dialog,
    DialogContent,
} from "@/components/ui/dialog"
import { ConfettiButton } from "../magicui/confetti"
import { NumberTicker } from "../magicui/number-ticker"
import Image from "next/image"
import { useUser } from "../providers/UserProvider";
import toast from "react-hot-toast";
import { useState } from "react";

interface ProModalProps {
    isOpen: boolean;
    onClose: () => void;
    isClaimable?: boolean | "reset";
    day?: string,
    checkpointId?: string,
    points?: number
    userId?: number
}

export function CheckInModel({
    isOpen,
    onClose,
    day,
    points,
    userId,
    checkpointId,
    isClaimable
}: ProModalProps) {
    const { user, updateUser } = useUser();
    const [isProcessing, setIsProcessing] = useState(false);
    const isCheckpointClaimed = user?.claimedCheckpoints.includes(checkpointId || '');

    const handleCheckIn = async () => {
        if (isProcessing) return;
        if (!userId) {
            toast.error("Please login to check in");
            return;
        }

        if (isCheckpointClaimed) {
            toast.error("You've already claimed this checkpoint");
            return;
        }

        try {
            setIsProcessing(true);
            const response = await fetch("/api/check-in", {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({
                    userId,
                    checkpointId,
                    points,
                    day,
                }),
            });

            const data = await response.json();

            if (!response.ok) {
                throw new Error(data.error || "Check-in failed");
            }

            updateUser({
                points,
                claimedCheckpoints: [checkpointId || ""],
                lastCheckIn: new Date(),
                lastClaimedDay: day
            });

            toast.success(`Check-in successful! Points: ${data.points}, Streak: ${data.streak}`);
            onClose();
        } catch (error) {
            console.error("Check-in error:", error);
            toast.error(error instanceof Error ? error.message : "Failed to check in. Please try again.");
        } finally {
            setIsProcessing(false);
        }
    };

    return (
        <>
            {isClaimable && !isCheckpointClaimed &&
                <Dialog open={isOpen} onOpenChange={onClose}>
                    <DialogContent className="bg-background/95 backdrop-blur-sm">
                        <div className="relative -z-50" id="stars2"></div>
                        <div className="relative -z-50" id="stars3"></div>
                        <div className="relative -z-50" id="stars"></div>
                        <div className='h-[95dvh] pb-8 flex-col w-full flex justify-center items-center'>
                            <div className='text-xl font-semibold text-center uppercase'>
                                <div className='text-3xl'>Day</div>
                                <NumberTicker
                                    value={Number(day?.slice(4))}
                                    className="whitespace-pre-wrap text-8xl font-medium tracking-tighter text-white"
                                />
                                <div>Streak</div>
                            </div>
                            <div className='flex-1 flex justify-center items-center flex-col'>
                                <Image
                                    alt=''
                                    src="https://stickers.fullyst.com/b844adbb-1c43-50a5-8a2d-7b9574ba0dbd/full/AgADSgIAAladvQo.webp"
                                    height={150}
                                    width={150}
                                    unoptimized
                                />
                                <p className='font-bold my-6 text-3xl'>
                                    {points}<span className='text-sm'>&nbsp;CPs</span>
                                </p>
                            </div>
                            <ConfettiButton
                                onClick={handleCheckIn}
                                disabled={isProcessing}
                                className={`w-full h-10 ${isProcessing ? 'opacity-50 cursor-not-allowed' : ''}`}
                            >
                                {isProcessing ? 'Processing...' : 'Check-In'}
                            </ConfettiButton>
                        </div>
                    </DialogContent>
                </Dialog>
            }
        </>
    )
}

import { prisma } from '../../../lib/prisma';
import { NextResponse } from 'next/server';

interface TaskCompletionRequest {
  userId: string;
  taskId: string;
  points: number;
}

export async function POST(request: Request): Promise<NextResponse> {
  try {
    const { userId, taskId, points }: TaskCompletionRequest = await request.json();

    // Validate and convert `userId` (telegramId) to an integer
    const telegramId = parseInt(userId, 10);
    if (isNaN(telegramId)) {
      return NextResponse.json({ error: 'Invalid user ID.' }, { status: 400 });
    }

    // Find the user by `telegramId`
    const user = await prisma.user.findFirst({
      where: { telegramId },
    });

    if (!user) {
      return NextResponse.json({ error: 'User not found.' }, { status: 404 });
    }

    // Check if the task has already been completed by the user
    const taskCompleted = await prisma.taskCompletion.findFirst({
      where: { userId: user.id, taskId },
    });

    if (taskCompleted) {
      return NextResponse.json({ error: 'Task already completed.' }, { status: 400 });
    }

    // Ensure points value is provided and valid
    if (typeof points !== 'number' || points <= 0) {
      return NextResponse.json({ error: 'Invalid points value.' }, { status: 400 });
    }

    // Create a task completion record
    await prisma.taskCompletion.create({
      data: { userId: user.id, taskId },
    });

    // Increment the user's points with the provided value
    await prisma.user.update({
      where: { id: user.id },
      data: { points: { increment: points } },
    });

    return NextResponse.json({
      success: true,
      message: `Task completed! You earned ${points} points.`,
    });
  } catch (error) {
    console.error('Error completing task:', error);
    return NextResponse.json({ error: 'Internal Server Error' }, { status: 500 });
  }
}

import { prisma } from '../../../lib/prisma';
import { NextRequest, NextResponse } from 'next/server';

export async function POST(request: NextRequest) {
    const { userId, referrerId } = await request.json();

    if (!userId || !referrerId) {
        return NextResponse.json({ error: 'Missing userId or referrerId' }, { status: 400 });
    }

    try {
        const existingUser = await prisma.user.findUnique({
            where: { telegramId: parseInt(userId) },
        });

        if (existingUser) {
            return NextResponse.json({ message: 'User already exists. No points awarded.' });
        }

        const referrer = await prisma.user.findUnique({
            where: { telegramId: parseInt(referrerId) },
        });

        if (!referrer) {
            return NextResponse.json({ error: 'Referrer not found' }, { status: 404 });
        }

        const newUser = await prisma.user.create({
            data: {
                telegramId: parseInt(userId),
                referredByTelegramId: referrer.telegramId,
                isNewUser: false
            },
        });

        await prisma.user.update({
            where: { telegramId: referrer.telegramId },
            data: { points: { increment: 500 } },
        });

        return NextResponse.json({ success: true, newUser, referrerPoints: referrer.points + 500 });
    } catch (error) {
        console.error('Error saving referral:', error);
        return NextResponse.json({ error: 'Failed to save referral' }, { status: 500 });
    }
}

export async function GET(request: NextRequest) {
    const userId = request.nextUrl.searchParams.get('userId');

    if (!userId) {
        return NextResponse.json({ error: 'Missing userId' }, { status: 400 });
    }

    try {
        const user = await prisma.user.findUnique({
            where: { telegramId: parseInt(userId) },
            include: {
                referrals: true,
                referredBy: true
            }
        });

        if (!user) {
            return NextResponse.json({ error: 'User not found' }, { status: 404 });
        }

        const response = {
            referrer: user.referredBy ? {
                telegramId: user.referredBy.telegramId,
                username: user.referredBy.username,
                firstName: user.referredBy.firstName,
                lastName: user.referredBy.lastName
            } : null,
            referrals: user.referrals.map((ref: { telegramId: number; username: string; firstName: string; lastName: string; }) => ({
                telegramId: ref.telegramId,
                username: ref.username,
                firstName: ref.firstName,
                lastName: ref.lastName
            }))
        };

        return NextResponse.json(response);
    } catch (error) {
        console.error('Error fetching referrals:', error);
        return NextResponse.json({ error: 'Failed to fetch referrals' }, { status: 500 });
    }
}

import { NextResponse } from "next/server";
import { prisma } from "../../../lib/prisma";

export async function POST(request: Request) {
  try {
    const { telegramId, points } = await request.json();

    if (!telegramId) {
      return NextResponse.json({ error: "Telegram ID is required." }, { status: 400 });
    }

    const telegramIdInt = parseInt(telegramId, 10);

    if (isNaN(telegramIdInt)) {
      return NextResponse.json({ error: "Invalid Telegram ID." }, { status: 400 });
    }   

    const user = await prisma.user.findUnique({
      where: { telegramId: telegramIdInt },
    });

    if (!user) {
      return NextResponse.json({ error: "User not found." }, { status: 404 });
    }

    if (user.hasClaimedWelcomePoints) {
      return NextResponse.json(
        { error: "You have already claimed your welcome points." },
        { status: 403 }
      );
    }

    const updatedUser = await prisma.user.update({
      where: { telegramId: telegramIdInt },
      data: {
        points: { increment: points },
        hasClaimedWelcomePoints: true,
        isNewUser: false,
      },
    });

    return NextResponse.json({ success: true, user: updatedUser }, { status: 200 });
  } catch (error) {
    console.error("Error claiming points:", error);
    return NextResponse.json({ error: "Internal Server Error" }, { status: 500 });
  }
}

import { NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';

export async function POST(req: Request) {
    try {
        const { userId, checkpointId, points, day } = await req.json();

        const numericUserId = Number(userId);
        if (isNaN(numericUserId)) {
            return NextResponse.json({ error: "Invalid userId" }, { status: 400 });
        }

        const user = await prisma.user.findUnique({ where: { telegramId: numericUserId } });

        if (!user) {
            return NextResponse.json({ error: 'User not found' }, { status: 404 });
        }

        if (user.claimedCheckpoints.includes(checkpointId)) {
            return NextResponse.json({ error: 'Already checked in' }, { status: 400 });
        }

        const today = new Date();
        today.setHours(0, 0, 0, 0);

        // If user has never checked in before or is starting over
        if (!user.lastCheckIn || user.streak === 0) {
            if (day !== "Day 01") {
                return NextResponse.json({ error: 'Must start with Day 01' }, { status: 400 });
            }

            const updatedUser = await prisma.user.update({
                where: { telegramId: numericUserId },
                data: {
                    points: { increment: points },
                    claimedCheckpoints: { push: checkpointId },
                    streak: 1,
                    lastCheckIn: today,
                    lastClaimedDay: day
                },
            });

            return NextResponse.json({ 
                points: updatedUser.points, 
                streak: updatedUser.streak,
                lastClaimedDay: updatedUser.lastClaimedDay 
            });
        }

        // For existing users, check the time difference
        const lastCheckIn = new Date(user.lastCheckIn);
        lastCheckIn.setHours(0, 0, 0, 0);

        const daysDifference = Math.floor((today.getTime() - lastCheckIn.getTime()) / (1000 * 60 * 60 * 24));

        // If trying to claim on the same day
        if (daysDifference === 0) {
            return NextResponse.json({ error: 'Already claimed today' }, { status: 400 });
        }

        // If streak is broken (more than 1 day has passed)
        if (daysDifference > 1) {
            if (day !== "Day 01") {
                return NextResponse.json({ error: 'Streak broken. Must start from Day 01' }, { status: 400 });
            }

            // Reset streak and start over
            const updatedUser = await prisma.user.update({
                where: { telegramId: numericUserId },
                data: {
                    points: { increment: points },
                    claimedCheckpoints: [checkpointId],
                    streak: 1,
                    lastCheckIn: today,
                    lastClaimedDay: "Day 01"
                },
            });

            return NextResponse.json({ 
                points: updatedUser.points, 
                streak: updatedUser.streak,
                lastClaimedDay: updatedUser.lastClaimedDay 
            });
        }

        // For consecutive days, verify correct day is being claimed
        const currentDayNumber = parseInt(user.lastClaimedDay.split(" ")[1]);
        const nextDayNumber = currentDayNumber + 1;
        const expectedNextDay = `Day ${String(nextDayNumber).padStart(2, '0')}`;

        if (day !== expectedNextDay) {
            return NextResponse.json({ 
                error: `Must claim ${expectedNextDay} next` 
            }, { status: 400 });
        }

        // Update user with new streak and checkpoint
        const updatedUser = await prisma.user.update({
            where: { telegramId: numericUserId },
            data: {
                points: { increment: points },
                claimedCheckpoints: { push: checkpointId },
                streak: { increment: 1 },
                lastCheckIn: today,
                lastClaimedDay: day
            },
        });

        return NextResponse.json({ 
            points: updatedUser.points, 
            streak: updatedUser.streak,
            lastClaimedDay: updatedUser.lastClaimedDay 
        });

    } catch (error) {
        console.error('Check-in error:', error);
        return NextResponse.json({ error: `Something went wrong: ${error}` }, { status: 500 });
    }
}

import { prisma } from '@/lib/prisma';
import { NextResponse } from 'next/server';

export async function POST(request: Request) {
    try {
        const { userId, referrerId } = await request.json();

        if (!userId || !referrerId) {
            return NextResponse.json({ error: 'Missing userId or referrerId' }, { status: 400 });
        }

        // Check if user already exists
        const existingUser = await prisma.user.findUnique({
            where: { telegramId: parseInt(userId) }
        });

        if (existingUser?.referredByTelegramId) {
            return NextResponse.json({ error: 'User already has a referrer' }, { status: 400 });
        }

        // Get referrer
        const referrer = await prisma.user.findUnique({
            where: { telegramId: parseInt(referrerId) }
        });

        if (!referrer) {
            return NextResponse.json({ error: 'Referrer not found' }, { status: 404 });
        }

        // Update user with referrer
        const updatedUser = await prisma.user.update({
            where: { telegramId: parseInt(userId) },
            data: { referredByTelegramId: parseInt(referrerId) }
        });

        // Calculate points based on premium status
        const pointsToAdd = existingUser?.isPremium ? 150 : 50;

        // Update referrer's points
        const updatedReferrer = await prisma.user.update({
            where: { telegramId: parseInt(referrerId) },
            data: { points: { increment: pointsToAdd } }
        });

        return NextResponse.json({
            success: true,
            user: updatedUser,
            referrer: updatedReferrer,
            pointsAdded: pointsToAdd
        });
    } catch (error) {
        console.error('Error processing referral:', error);
        return NextResponse.json({ error: 'Failed to process referral' }, { status: 500 });
    }
}

import { NextResponse } from "next/server";
import { prisma } from "../../../lib/prisma";

// Define types for request and response
interface User {
  userId: number;
  username: string;
  firstName: string;
  lastName: string;
  points: number;
  photoUrl: string;
  hasClaimedWelcomePoints: boolean;
  isPremium: boolean;
  streak: number;
  lastCheckIn?: Date;
  claimedCheckpoints: string[];
  gifts: string[];
  taskCompletions?: { taskId: string }[];
  lastClaimedDay: string;
  referrals?: User[];
  referredBy?: User | null;
  isNewUser: boolean;
  walletAddress?: string;
  isWalletConnected: boolean;
  dailyPlays: number;
  lastPlayedDate?: Date;
}

// GET user with completed tasks and referral info
export async function GET(req: Request): Promise<NextResponse> {
  try {
    const { searchParams } = new URL(req.url);
    const telegramId = searchParams.get("telegramId");

    if (!telegramId) {
      return NextResponse.json(
        { error: "Invalid user data: telegramId is missing" },
        { status: 400 }
      );
    }

    const user = await prisma.user.findUnique({
      where: { telegramId: parseInt(telegramId) },
      include: {
        taskCompletions: true,
        referrals: true,
        referredBy: true,
      },
    });

    if (!user) {
      return NextResponse.json({ error: "User not found" }, { status: 404 });
    }

    const completedTaskIds = user.taskCompletions?.map((tc: { taskId: string; }) => tc.taskId) || [];

    return NextResponse.json({
      telegramId: user.telegramId,
      username: user.username,
      firstName: user.firstName,
      lastName: user.lastName,
      points: user.points,
      isPremium: user.isPremium,
      photoUrl: user.photoUrl,
      hasClaimedWelcomePoints: user.hasClaimedWelcomePoints,
      streak: user.streak,
      lastCheckIn: user.lastCheckIn,
      claimedCheckpoints: user.claimedCheckpoints,
      gifts: user.gifts,
      lastClaimedDay: user.lastClaimedDay,
      completedTaskIds,
      referrals: user.referrals,
      referredBy: user.referredBy,
      isNewUser: user.isNewUser,
      walletAddress: user.walletAddress,
      isWalletConnected: user.isWalletConnected,
      dailyPlays: user.dailyPlays,
      lastPlayedDate: user.lastPlayedDate
    });
  } catch (error) {
    console.error("Error fetching user data:", error);
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 }
    );
  }
}

// POST to create or fetch a user
export async function POST(req: Request): Promise<NextResponse> {
  try {
    const userData: Partial<User> = await req.json();

    if (!userData || !userData.userId) {
      return NextResponse.json(
        { error: "Invalid user data: telegramId is missing" },
        { status: 400 }
      );
    }

    let user = await prisma.user.findUnique({
      where: { telegramId: userData.userId },
      include: {
        taskCompletions: true,
        referrals: true,
        referredBy: true,
      },
    });

    if (!user) {
      user = await prisma.user.create({
        data: {
          telegramId: userData.userId,
          username: userData.username || "",
          firstName: userData.firstName || "",
          lastName: userData.lastName || "",
          isPremium: userData.isPremium || false,
          points: 0,
          photoUrl: userData.photoUrl || "",
          hasClaimedWelcomePoints: false,
          streak: 0,
          lastCheckIn: null,
          lastClaimedDay: "",
          claimedCheckpoints: [],
          gifts: [],
          isNewUser: true,
          walletAddress: null,
          isWalletConnected: false,
          dailyPlays: 0,
          lastPlayedDate: null
        },
        include: {
          taskCompletions: true,
          referrals: true,
          referredBy: true,
        },
      });
    }

    const completedTaskIds = user.taskCompletions?.map((tc: { taskId: string; }) => tc.taskId) || [];

    return NextResponse.json({
      telegramId: user.telegramId,
      username: user.username,
      firstName: user.firstName,
      lastName: user.lastName,
      points: user.points,
      photoUrl: user.photoUrl,
      isPremium: user.isPremium,
      hasClaimedWelcomePoints: user.hasClaimedWelcomePoints,
      streak: user.streak,
      lastCheckIn: user.lastCheckIn,
      lastClaimedDay: user.lastClaimedDay,
      claimedCheckpoints: user.claimedCheckpoints,
      gifts: user.gifts,
      completedTaskIds,
      referrals: user.referrals,
      referredBy: user.referredBy,
      isNewUser: user.isNewUser,
      walletAddress: user.walletAddress,
      isWalletConnected: user.isWalletConnected,
      dailyPlays: user.dailyPlays,
      lastPlayedDate: user.lastPlayedDate
    });
  } catch (error) {
    console.error("Error processing user data:", error);
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 }
    );
  }
}

import { NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";

export async function POST(req: Request) {
  try {
    const { userId } = await req.json();

    if (!userId) {
      return NextResponse.json({ error: "User ID is required" }, { status: 400 });
    }

    // Update the user in the database
    const updatedUser = await prisma.user.update({
      where: { telegramId: userId },
      data: {
        claimedCheckpoints: [],
        lastCheckIn: null,
        lastClaimedDay: "",
      },
    });

    return NextResponse.json({ success: true, user: updatedUser });
  } catch (error) {
    console.error("Error resetting check-in data:", error);
    return NextResponse.json({ error: "Internal Server Error" }, { status: 500 });
  }
}

